auto r = dedupe_last({"a","b","a","c"});
CHECK_EQ(r.size(), 3);
CHECK_EQ(r[0], std::string("b"));
CHECK_EQ(r[1], std::string("a"));
CHECK_EQ(r[2], std::string("c"));

auto r = dedupe_last({"x","y"});
CHECK_EQ(r.size(), 2);
CHECK_EQ(r[0], std::string("x"));

auto r = dedupe_last({"z","z","z"});
CHECK_EQ(r.size(), 1);
CHECK_EQ(r[0], std::string("z"));
